var n = 20;
var colors = [[255], [0]];

function setup() {
  createCanvas(500, 500);
  noStroke();
}

function draw() {
  background(colors[0]);
  let t = frameCount/100;

  let s = width/n;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      let x = i*s, y = j*s;
			let r = noise(i, j, t);
			let thresh = (sin(dist(x, y, width/2, height/2)/100-t)+1)/2
      if ((i+j)%2 == 0) {
        if (r < thresh) {
          fill(colors[1]);
          arc(x, y, s, s, 0, HALF_PI);
          arc(x+s, y+s, s, s, PI, 3*HALF_PI);
        } else {
          fill(colors[1]);
          square(x, y, s);
          fill(colors[0]);
          arc(x+s, y, s, s, HALF_PI, PI);
          arc(x, y+s, s, s, 3*HALF_PI, 0);
        }
      } else {
        if (r < thresh) {
          fill(colors[1]);
          arc(x, y+s, s, s, 3*HALF_PI, 0);
          arc(x+s, y, s, s, HALF_PI, PI);
        } else {
          fill(colors[1]);
          square(x, y, s);
          fill(colors[0]);
          arc(x, y, s, s, 0, HALF_PI);
          arc(x+s, y+s, s, s, PI, 3*HALF_PI);
        }
      }
    }
  }
}
